// the vault is one autobase with 2 views, the bee (automap) and the audit log (auditcore), so one apply sees both
// and the base has one set of writers. create_automap({ base }) and create_auditcore({ base }) give their usual api on it.
// measured against 2 separate autobases in docs/vault-views-check.js
const Autobase = require('autobase')
const { open_bee, apply_bee } = require('automap')
const { open_log, apply_log } = require('auditcore')

module.exports = { create_vault_base }

// entries the audit log appends say view: 'log', everything else (put, del, the writers) goes to the bee
function create_vault_base (store, bootstrap = null) {
  return new Autobase(store, bootstrap, {
    valueEncoding: 'json',
    open: view_store => ({ bee: open_bee(view_store), log: open_log(view_store) }),
    apply,
    ackInterval: 1000,
    ackThreshold: 1,
    fastForward: false
  })
}

async function apply (nodes, view, base) {
  const logged = nodes.filter(node => node.value?.view === 'log')
  await apply_bee(nodes.filter(node => !logged.includes(node)), view.bee, base)
  await apply_log(logged, view.log)
}
